from datetime import datetime, timedelta

from taf.rfrl.procedures.resources.python.logger import log_step, log_result, log_env_state, log_operation, log_input_and_output, log_to_console

from taf.rfrl.procedures.resources.python.counters.core.interface import Core
from taf.rfrl.procedures.resources.python.counters.real_time.exceptions import (
    PowerMeasurementValueZero, VoltageMeasurementValueIncorrect, NoMeasurementsFound, MaxPowerConsumptionExceeded,
    IncorrectCabinetTemperature
)
from taf.rfrl.procedures.resources.python.wait import wait_until_specific_time_passed
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import translate_rmod_index_to_runtime


class RealTime(Core):
    def __init__(self):
        super(RealTime, self).__init__()

    def load_real_time_measurements(self, timeout=180, connection=None):
        """
        Loads Real Time Measurements from BTS via API and saves them under `real_time_measurements` attribute.

        :param timeout: timeout for API command of getting Real Time Measurements.
        :type timeout: int
        :param connection: connection to be used for API command
        :type connection: str
        """
        log_step("Getting Real Time Measurements dictionary via API...")
        self.real_time_measurements = self.api.get_measurements(
            measurement_type="realTime", timeout=timeout, connection=connection or self.api_connection_alias
        )
        log_result("Real Time Measurements read successfully")

    def get_real_time_measurements_list(self, number_of_iterations, additional_wait=True, connection=None):
        """
        Creates a list of real time measurements that is updated
        for a number of times equal to number_of_iterations.

        According to LTE_OPR_REQ_9397 one or two first measurements collected after enabling
        the actPowerMeter might equal zero or be unavailable - in order to skip those, there is a 120 seconds
        sleep before entering the real time measurements loading loop. This option can be disabled by setting
        additional_wait to False.

        As real time measurements are updated each 60s, there is a sleep between the iterations
        so that new measurements can be generated and saved to list.

        :param number_of_iterations: desired number of real time measurements (collected each 60s)
        :type number_of_iterations: int or str
        :param additional_wait: if True, additional 120 seconds wait will be performed before starting the loop
        :type additional_wait: bool
        :param connection: connection to be used for API command
        :type connection: str
        """
        measurements = []
        log_step("Waiting 120 seconds to skip potential zeros in two initial real time measurements")
        start = datetime.now()
        if additional_wait:
            wait_until_specific_time_passed(start, "120 seconds")

        for iteration in range(1, int(number_of_iterations) + 1):
            log_step("Getting Real Time Measurements, iteration {}/{}".format(iteration, number_of_iterations))
            start = datetime.now()
            self.load_real_time_measurements(connection=connection if connection else self.api_connection_alias)
            self.real_time_measurements = self._add_timestamp_to_measurements(self.real_time_measurements)
            measurements.extend(self.real_time_measurements)

            log_step("Waiting for 60 seconds for the next real time measurement")
            wait_until_specific_time_passed(start, "60 seconds")

        log_result("Real Time Measurements collection completed {} times".format(number_of_iterations))
        return measurements

    def verify_real_time_measurements_for_specific_rmods(
            self, list_of_ru_ids, number_of_iterations
    ):
        """
        Verifies Real Time measurements list and checks if the values
        for RMODs listed in list_of_ru_ids are in correct range.

        Power values should not be zero at any time, voltage values should be in range 47-57V

        :param list_of_ru_ids: list of RMOD IDs for which verification will be performed
        :type list_of_ru_ids: list[int]
        :param number_of_iterations: desired number of real time measurements (collected each 60s)
        :type number_of_iterations: int
        """
        measurements_list = self.get_real_time_measurements_list(int(number_of_iterations))
        log_env_state(
            "Real Time measurements list for all modules: {}".format(
                str(measurements_list)
            )
        )

        for ru_id in list_of_ru_ids:
            for measurement in measurements_list:
                for module_name, value in measurement.items():
                    if module_name == "ENERGY_EFFICIENCY/RMOD/RMOD_R-{}".format(ru_id):
                        if float(value["power"]) == 0.0:
                            raise PowerMeasurementValueZero(
                                "One of the power measurements"
                                " for RMOD-{} equals zero!".format(ru_id)
                            )
                        if float(value["voltage"]) < 47.0 or float(value["voltage"]) > 57.0:
                            raise VoltageMeasurementValueIncorrect(
                                "One or more of the voltage measurements for RMOD-{} is not "
                                "in desired range (47 - 57V)".format(ru_id)
                            )
        log_result("Real Time Measurements Verification Complete!")

    def get_average_value_of_real_time_measurement(self, measurements, module_name, value_name):
        """
        Calculates average value of real time measurement for given module_name

        :param measurements: list of real time measurements
        :type measurements: list[dict]
        :param module_name: name of the module for which average value will be calculated
                            e.g. "ENERGY_EFFICIENCY/RMOD/RMOD_R-2"
        :type module_name: str
        :param value_name: name of the value for which average value will be calculated, e.g. "power", "voltage"
        :type value_name: str
        :return: average value of real time measurement for given module_name
        :rtype: float
        """
        values = []
        try:
            for measurement in measurements:
                for key, value in measurement.items():
                    if key == module_name:
                        values.append(float(value[value_name]))
        except KeyError:
            raise NoMeasurementsFound("No {} measurements from module {} were found, "
                                      "impossible to calculate average!".format(value_name, module_name))
        return sum(values) / len(values)

    @log_input_and_output
    def verify_rmod_power_consumption_measurements(self, rmod_id, measurements, max_power_consumption):
        """
        Verifies based on the provided measurements whether the power consumption for the given RMOD ID
        does not exceed the maximum power consumption threshold. The verification is performed on each measurement.

        :param rmod_id: Configured RMOD ID for which verification will be performed.
        :type rmod_id: int or str
        :param measurements: Filtered list with ENERGY_EFFICIENCY and RMOD real time measurements e.g.
                             [{'ENERGY_EFFICIENCY/RMOD/RMOD_R-1': {'voltage': '53.2', 'power': '120.6', 'timestamp': '15:28'}},
                              {'ENERGY_EFFICIENCY/RMOD/RMOD_R-2': {'voltage': '53.1', 'power': '172.8', 'timestamp': '15:28'}}]
        :type measurements: list[dict]
        :param max_power_consumption: Maximum power consumption in watts [W], value should be described in the RMOD specification.
        :type max_power_consumption: float or str
        :rtype: bool
        :raises: NoMeasurementsFound, PowerMeasurementValueZero, MaxPowerConsumptionExceeded
        """
        runtime_rmod_id = translate_rmod_index_to_runtime(rmod_index=rmod_id, connection=self.api_connection_alias)
        runtime_module_name = f"RMOD_R-{runtime_rmod_id}"
        rmod_measurements = self._parse_measurements_for_module(measurements, runtime_module_name, "power")
        log_operation(f"Measurements from RMOD-{rmod_id}\n {rmod_measurements}")

        if not rmod_measurements[runtime_module_name]:
            raise NoMeasurementsFound(f"No power measurements found for RMOD-{rmod_id}!")

        measurements_above_threshold = []
        for power_consumption, timestamp in rmod_measurements[runtime_module_name]:
            if float(power_consumption) == 0.0:
                raise PowerMeasurementValueZero(f"Power measurement for RMOD-{rmod_id} equals zero! Timestamp: {timestamp}")
            if float(power_consumption) > float(max_power_consumption):
                measurements_above_threshold.append((power_consumption, timestamp))

        if measurements_above_threshold:
            raise MaxPowerConsumptionExceeded(f"Power consumption for RMOD-{rmod_id} has exceeded the maximum threshold. "
                                              f"Maximum allowed: {max_power_consumption} W! "
                                              f"Measurements above threshold: {measurements_above_threshold}")

        power_values = [float(power_consumption) for power_consumption, _ in rmod_measurements[runtime_module_name]]
        avrg_power_consumption = round((sum(power_values) / len(power_values)), 2)
        log_operation(f'Power consumption RMOD-{rmod_id} average: {avrg_power_consumption} W')
        log_to_console(f"RMOD-{rmod_id} power consumption verification completed successfully.\n"
                       f"{' ' * 9} Average consumption: {avrg_power_consumption } W, Maximum allowed: {max_power_consumption} W")

    @log_input_and_output
    def verify_cabinet_temperature_measurements(self, measurements, max_temperature, min_temperature):
        """
        Verifies based on the provided measurements whether the cabinet temperature is within the acceptable range.
        The verification is performed on each measurement.

        :param measurements: list with cabinet's temperature real-time measurements e.g.
                             [{'TEMPERATURE/CABINET-4113/Front sensor':
                                  {'timeOfLastReportedTemperature': '16.10.2025 08:39:27 GMT+0200 DST',
                                   'lastReportedTemperature': '22.00',
                                   'temperature': '22.00',
                                   'timestamp': '08:40'}},
                              {'TEMPERATURE/CABINET-4113/Front sensor':
                                  {'timeOfLastReportedTemperature': '16.10.2025 08:40:27 GMT+0200 DST',
                                  'lastReportedTemperature': '22.00',
                                  'temperature': '22.00',
                                  'timestamp': '08:41'}}]
        :type measurements: list[dict]
        :param max_temperature: maximum acceptable temperature in Celsius degrees [°C].
        :type max_temperature: float or str
        :param min_temperature: minimum acceptable temperature in Celsius degrees [°C].
        :type min_temperature: float or str
        :raises: NoMeasurementsFound, IncorrectCabinetTemperature
        """
        if not measurements:
            raise NoMeasurementsFound("Temperature measurements list is empty!")

        incorrect_measurements = {}
        for measurement in measurements:
            temperature_info = next(iter(measurement.values()))
            log_operation(f'Verifying cabinet temperature from: {temperature_info["timeOfLastReportedTemperature"]}')
            log_step(f'Reported temperature: {temperature_info["lastReportedTemperature"]}')

            if (float(temperature_info["lastReportedTemperature"]) > float(max_temperature)
                    or float(temperature_info["lastReportedTemperature"]) < float(min_temperature)):
                incorrect_measurements[temperature_info["timeOfLastReportedTemperature"]] = temperature_info["lastReportedTemperature"]
            else:
                log_result(f'Cabinet temperature {temperature_info["lastReportedTemperature"]}°C is within '
                           f'the acceptable range ({min_temperature}°C - {max_temperature}°C)')

        if incorrect_measurements:
            raise IncorrectCabinetTemperature(
                f"Some of cabinet temperature measurements are below the minimum threshold of {min_temperature}°C "
                f"or above the maximum threshold of {max_temperature}°C. \n"
                f"Recorded incorrect measurements: {incorrect_measurements}")

    @log_input_and_output
    def filter_measurement_results(self, measurements, collection=None, module_name=None):
        """
        Filters measurements for specific collection and module name.

        :param measurements: List of real time measurements e.g.
                             [{'ENERGY_EFFICIENCY/RMOD/RMOD_R-1': {'voltage': '53.2', 'power': '120.6', 'timestamp': '15:28'}},
                              {'VSWR/RMOD_R-1/ANTL_R-2/TX bands - B3, n3': '-'}, {'VSWR/RMOD_R-1/ANTL_R-6/TX bands - B3, n3': '-'}]
        :type measurements: list[dict]
        :param collection: Name of the collection by which measurements will be filtered. Only one of the following can be chosen:
                           <'ENERGY_EFFICIENCY' | 'VSWR' | 'TEMPERATURE' | None>.
                           Default is None, which means that all collections will be considered.
        :param module_name: Name of the module by which measurements will be filtered. Only one of the following can be chosen:
                            <'BBMOD' | 'SMOD' | 'RMOD' | 'CABINET' | None>.
                            Default is None, which means that all modules will be considered.
        :type module_name: str
        :return: List of measurements for specific collection and module names
        :rtype: list[dict]
        """
        filtered = [
            measurement for measurement in measurements
            if (module_name is None or module_name in next(iter(measurement.keys())))
            and (collection is None or collection in next(iter(measurement.keys())))
        ]
        return filtered

    def get_measurement_end_time(self, duration):
        """
        Calculate the end time of a measurement based on the provided duration.
        param: duration: Duration of the measurement in minutes.
        type: duration: str or int
        """
        finish_time = datetime.now() + timedelta(minutes=int(duration))
        return finish_time.strftime('%Y-%m-%d %H:%M:%S')

    def _parse_measurements_for_module(self, measurements, runtime_module_name, measurement_type):
        """
        Parse and group measurements for a specific runtime module.
        param: measurements: List of real time measurements.
        type: measurements: list[dict] e.g. [{'ENERGY_EFFICIENCY/RMOD/RMOD_R-1': {'power': '122.0', 'timestamp': '18:21'}},
                                             {'ENERGY_EFFICIENCY/RMOD/RMOD_R-1': {'power': '171.5', 'timestamp': '18:22'}}]
        param: runtime_module_name: Name of the runtime module for which measurements will be parsed. e.g 'RMOD_R-1'
        type: runtime_module_name: str
        param: measurement_type: Type of measurements that will be grouped into one list, e.g., 'power'.
        type: measurement_type: str
        return: Dictionary with runtime module name as key and list of tuples (measurement, timestamp).
                e.g. {'RMOD_R-1': [(122.0, 18:21), (171.5, 18:22)]}
        rtype: dict
        """
        return {
            runtime_module_name: [(value[measurement_type], value['timestamp']) for measurement in measurements
                                  for key, value in measurement.items() if runtime_module_name in key]
        }

    def _add_timestamp_to_measurements(self, measurements):
        """
        Adds timestamp to measurements.
        :param measurements: List of real time measurements
        :type measurements: list[dict]
        :return: list of measurements with timestamp added
        :rtype: list[dict]
        """
        for measurement in measurements:
            for key, value in measurement.items():
                if isinstance(value, dict):
                    measurement[key]["timestamp"] = datetime.now().strftime("%H:%M")
        return measurements
